            if self.current_level == self.end_pos[2]: gx, gy = self.renderer.get_pixel(self.end_pos[0], self.end_pos[1]); arcade.draw_circle_filled(gx, gy, self.renderer.cell_radius*0.4, config.GOAL_COLOR)

            # Player Visibility
            self.player_list.draw()

            # 3. Apply Light Map (Multiply Blend)
            if self.dark_mode and self.player_sprite:
                try:
                    # Switch to GUI camera (Screen Space)
                    self.gui_camera.use()

                    self.window.ctx.enable_only(self.window.ctx.BLEND)
                    self.window.ctx.blend_func = self.window.ctx.BLEND_MULTIPLY

                    # Draw the texture
                    self.light_layer.color_attachments[0].use(0)
                    arcade.draw_lrwh_rectangle_textured(0, 0, config.SCREEN_WIDTH, config.SCREEN_HEIGHT, self.light_layer.color_attachments[0])
                except Exception:
